use std::{ffi::{CString,c_void},hint::black_box};
use birnam_native_compiler::Unit;
use birnam_abi::{Oop,id_protocol::{Operand,Outcome}};
type Plain = unsafe extern "C" fn(*mut c_void,Oop,*const Oop,usize)->Oop;
type Packet = unsafe extern "C" fn(*mut c_void,Oop,*const Operand,usize)->Outcome;
unsafe extern "C" {fn clock_gettime_nsec_np(clock:i32)->u64;}
#[inline(never)]
unsafe extern "C" fn rust_plain(_: *mut c_void, receiver:Oop, args:*const Oop,n:usize)->Oop {
 if n==0 {receiver} else {unsafe{args.add(n-1).read()}}
}
#[inline(never)]
unsafe extern "C" fn rust_packet(_: *mut c_void, receiver:Oop,args:*const Operand,n:usize)->Outcome {
 Outcome::loaded(if n==0 {Operand::object(receiver)} else {unsafe{args.add(n-1).read()}})
}
fn main(){unsafe{
 let src=CString::new(include_str!("probe.c")).unwrap();
 let unit=Unit::compile(&src,&[(c"rust_plain",rust_plain as *const c_void),(c"rust_packet",rust_packet as *const c_void)]).expect("vendored TCC compilation");
 let c_plain:Plain=std::mem::transmute(unit.symbol(c"c_plain").unwrap().as_ptr());
 let c_packet:Packet=std::mem::transmute(unit.symbol(c"c_packet").unwrap().as_ptr());
 let c_reenter:Plain=std::mem::transmute(unit.symbol(c"c_reenter").unwrap().as_ptr());
 let drive_plain:unsafe extern "C" fn(usize,Oop,*const Oop,usize)->Oop=std::mem::transmute(unit.symbol(c"drive_plain").unwrap().as_ptr());
 let drive_packet:unsafe extern "C" fn(usize,Oop,*const Operand,usize)->Oop=std::mem::transmute(unit.symbol(c"drive_packet").unwrap().as_ptr());
 let mut payloads=Box::new([0usize;66]);
 let vals:Vec<Oop>=payloads.iter_mut().map(|v|std::ptr::from_mut(v).cast()).collect();
 let packets:Vec<_>=vals.iter().map(|&v|Operand::object(v)).collect();
 let receiver=vals[65];
 for n in [0,1,4,8,17,64] {
  let expected=if n==0 {receiver}else{vals[n-1]};
  assert_eq!(c_plain(std::ptr::null_mut(),receiver,vals.as_ptr(),n),expected);
  assert_eq!(c_reenter(std::ptr::null_mut(),receiver,vals.as_ptr(),n),expected);
  assert_eq!(c_packet(std::ptr::null_mut(),receiver,packets.as_ptr(),n).value.as_object(),Some(expected));
 }
 println!("{{\"check\":\"rust_to_tcc_and_tcc_to_rust_roundtrip\",\"arities\":[0,1,4,8,17,64],\"passed\":true,\"scope\":\"transport only, no production dispatch or GC\"}}");
 let iterations=2_000_000;
 for run in 0..6 {for lane in if run%2==0 {["oop","packet"]}else{["packet","oop"]} {
  let t=clock_gettime_nsec_np(16);
  let result=if lane=="oop" {drive_plain(iterations,receiver,vals.as_ptr(),4)}else{drive_packet(iterations,receiver,packets.as_ptr(),4)};
  let elapsed=clock_gettime_nsec_np(16)-t;
  assert_eq!(black_box(result),vals[3]);
  println!("{{\"run\":{run},\"lane\":\"{lane}\",\"iterations\":{iterations},\"cpu_ns_per_call\":{}}}",elapsed as f64/iterations as f64);
 }}
}}

