#include <stddef.h>
#include <stdint.h>
typedef void *O;
typedef struct A A;
typedef struct R R;
typedef R (*Entry)(void*,O,const A*,size_t);
struct A {uint32_t kind,reserved;union{O object;size_t word;struct{const unsigned char *p;size_t n;} bytes;struct{Entry method;void *context;} entry;const void *protocol;} data;};
struct R {uint32_t status,reserved;size_t detail;A value;};
extern O rust_plain(void*,O,const O*,size_t);
extern R rust_packet(void*,O,const A*,size_t);
O c_plain(void*c,O self,const O*a,size_t n){return n?a[n-1]:self;}
R c_packet(void*c,O self,const A*a,size_t n){R r={0};if(n)r.value=a[n-1];else {r.value.kind=1;r.value.data.object=self;}return r;}
O c_reenter(void*c,O self,const O*a,size_t n){return rust_plain(c,self,a,n);}
O drive_plain(size_t iterations,O self,const O*a,size_t n){O result=self;for(size_t i=0;i<iterations;i++)result=rust_plain(0,self,a,n);return result;}
O drive_packet(size_t iterations,O self,const A*a,size_t n){R result={0};for(size_t i=0;i<iterations;i++)result=rust_packet(0,self,a,n);return result.value.data.object;}
